\title{Topological Quantum Codes from Cellular Homology:\\
Logical Qubits as Betti Numbers and Distance as the Systole}
\author{Aristotle}
\date{July 11, 2026}

\begin{document}

\begin{abstract}
We develop the homological theory of Calderbank--Shor--Steane (CSS) quantum
error-correcting codes over the binary field $\FF$, presenting every such code as
a length-three chain complex $C_2 \xrightarrow{\dd_2} C_1 \xrightarrow{\dd_1} C_0$
with $\dd_1 \circ \dd_2 = 0$. The physical qubits are the middle chains $C_1$, the
stabilizers are the rows of the two boundary maps, and the encoded logical qubits
are the first homology group $H_1 = \ker\dd_1 / \im\dd_2$. We prove four principal
results. First, the \emph{CSS Dimension Theorem}: $k + \rank\dd_1 + \rank\dd_2 =
n$. Second, the \emph{Homological Information Criterion}: a code stores at least
one logical qubit iff $\im\dd_2 \subsetneq \ker\dd_1$. Third, the \emph{Genus
Theorem}: the minimal complex of a closed orientable genus-$g$ surface encodes
exactly $k = 2g$ logical qubits and recovers $\ch = 2 - 2g$. Fourth, we define
code distance as the \emph{homological systole} and establish positivity and the
shortest-loop bound, illustrated by an explicit $[[3,1,3]]$ triangle code with
nonzero boundary map. We close with conjectures on homological packing bounds,
topological invariance of the rate, and the advantage of hyperbolic
tessellations.
\end{abstract}

\maketitle

\section{Introduction}
Quantum information is fragile: local interactions with the environment rapidly
decohere superpositions. Quantum error correction protects information by encoding
a few \emph{logical} qubits into many \emph{physical} qubits, so that low-weight
errors can be detected and reversed by measuring commuting parity checks
(\emph{stabilizers}). The surface code and its relatives store logical information
not in any local subsystem but in a \emph{global topological} degree of freedom of
a cellulated surface, immune to local error.

We make the slogan ``logical qubits $=$ homology, distance $=$ systole'' precise
as exact theorems for a general CSS code presented as a chain complex over $\FF$.
The result is a dictionary between coding theory and algebraic topology in which
the code parameters $[[n,k,d]]$ are, respectively, the dimension of the chain
space, the first Betti number, and the systole. Throughout, $\FF = \{0,1\}$ with
$1+1=0$; all vector spaces are finite dimensional over $\FF$ and $\dim$ is
dimension over $\FF$.

\section{Chain complexes and CSS codes}

\begin{definition}[CSS code as chain complex]
A \emph{binary CSS code} is a triple of finite-dimensional $\FF$-vector spaces
with two linear boundary maps
\[ C_2 \xrightarrow{\ \dd_2\ } C_1 \xrightarrow{\ \dd_1\ } C_0, \qquad
\dd_1 \circ \dd_2 = 0. \]
We take $C_j = \FF^{\,n_j}$; the integer $n_1 =: n$ is the number of \emph{physical
qubits}. The rows of $\dd_1$ are the $Z$-type stabilizers and the columns of
$\dd_2$ the $X$-type stabilizers; the chain-complex condition encodes their
commutation.
\end{definition}

\begin{definition}[cycles, boundaries, homology]
Set $Z := \ker\dd_1$ (the $Z$-cycles) and $B := \im\dd_2$ (the $Z$-boundaries).
The chain-complex condition gives $B \subseteq Z$, since $\dd_1(\dd_2 x) = 0$. The
\emph{first homology group} is $H_1 := Z/B = \ker\dd_1/\im\dd_2$.
\end{definition}

\begin{definition}[logical qubits]
The number of \emph{logical qubits} is
\[ k := \dim H_1 = \dim(\ker\dd_1) - \dim(\im\dd_2), \]
well posed since $B \subseteq Z$. Write $\rank\dd_1 = \dim(\im\dd_1)$ and
$\rank\dd_2 = \dim(\im\dd_2)$ for the ranks of the stabilizer matrices.
\end{definition}

\begin{theorem}[CSS Dimension Theorem]\label{thm:dim}
For every CSS code, $\; k + \rank\dd_1 + \rank\dd_2 = n.$
\end{theorem}
\begin{proof}[Proof sketch]
Rank--nullity for $\dd_1 : C_1 \to C_0$ gives $\dim(\ker\dd_1) + \rank\dd_1 = n$.
By definition $k = \dim(\ker\dd_1) - \rank\dd_2$. Substituting
$\dim(\ker\dd_1) = k + \rank\dd_2$ and using $\rank\dd_2 = \dim B \le
\dim(\ker\dd_1)$ (from $B \subseteq Z$) to justify the natural-number subtraction
yields $k + \rank\dd_2 + \rank\dd_1 = n$.
\end{proof}

This is a conservation law: each physical qubit is either consumed by an
independent stabilizer or contributes to logical information, and it gives a
matrix recipe for $k$.

\begin{theorem}[Homological Information Criterion]\label{thm:info}
A CSS code satisfies $k \ge 1$ if and only if $B \subsetneq Z$, i.e.\ $H_1 \ne 0$.
\end{theorem}
\begin{proof}[Proof sketch]
($\Leftarrow$) Strict inclusion of finite-dimensional spaces forces $\dim B <
\dim Z$, so $k \ge 1$. ($\Rightarrow$) $k \ge 1$ gives $\dim B < \dim Z$, so
$B \ne Z$; with $B \subseteq Z$ this is $B \subsetneq Z$.
\end{proof}

\section{The genus-$g$ surface code}

\begin{definition}[minimal surface complex]
The closed orientable genus-$g$ surface has a minimal CW decomposition with one
$0$-cell, $2g$ $1$-cells, and one $2$-cell attached along $\prod_{i=1}^g [a_i,
b_i]$. As a CSS code, $n_0 = 1$, $n_1 = 2g$, $n_2 = 1$, and both boundary maps
vanish: over $\FF$ each generator occurs an even number of times in the attaching
word, so $\dd_2 = 0$; every $1$-cell is a loop at the single vertex, so
$\dd_1 = 0$.
\end{definition}

\begin{theorem}[Genus Theorem]\label{thm:genus}
The genus-$g$ surface code encodes exactly $k = 2g$ logical qubits.
\end{theorem}
\begin{proof}[Proof sketch]
With $\dd_1 = 0$, $\ker\dd_1 = C_1 = \FF^{2g}$, so $\dim Z = 2g$. With $\dd_2 = 0$,
$B = 0$, so $\dim B = 0$. Hence $k = 2g$.
\end{proof}

\begin{corollary}[Euler characteristic]
With Betti numbers $b_0 = 1$, $b_1 = 2g$, $b_2 = 1$,
\[ \ch = b_0 - b_1 + b_2 = 1 - 2g + 1 = 2 - 2g, \]
the classical Euler characteristic of the genus-$g$ surface.
\end{corollary}

\section{Code distance as the homological systole}

\begin{definition}[systole / code distance]
Let $S := \{\, |v| : v \in Z,\ v \notin B \,\}$, where $|v|$ is the Hamming
weight. The \emph{code distance} is the systole
\[ d := \inf S = \min\{\, |v| : v \in \ker\dd_1,\ v \notin \im\dd_2 \,\}, \]
the minimum weight of a $Z$-cycle that is not a $Z$-boundary.
\end{definition}

\begin{lemma}[nontriviality implies nonzero]\label{lem:nz}
If $v \notin B$ then $v \ne 0$.
\end{lemma}
\begin{proof}[Proof sketch]
$0 = \dd_2 0 \in B$, so $v \notin B$ forces $v \ne 0$.
\end{proof}

\begin{lemma}[weight positivity]\label{lem:wpos}
If $v \notin B$ then $|v| \ge 1$.
\end{lemma}
\begin{proof}[Proof sketch]
By Lemma~\ref{lem:nz}, $v \ne 0$, so it has a nonzero coordinate.
\end{proof}

\begin{proposition}[shortest-loop upper bound]\label{prop:ub}
If $v \in Z$ and $v \notin B$ then $d \le |v|$.
\end{proposition}
\begin{proof}[Proof sketch]
$|v| \in S$, and $\inf S$ is a lower bound of $S$.
\end{proof}

\begin{proposition}[distance positivity]\label{prop:pos}
If $k \ge 1$ then $d \ge 1$.
\end{proposition}
\begin{proof}[Proof sketch]
By Theorem~\ref{thm:info} there is $v \in Z \setminus B$, so $S \ne \emptyset$;
every element of $S$ is $\ge 1$ by Lemma~\ref{lem:wpos}, so $\inf S \ge 1$.
\end{proof}

\section{A fully explicit code: the triangle $C_3$}

\begin{definition}[triangle code]
Let $C_3$ be the triangle graph: three vertices, three edges. Put one qubit per
edge, three vertex checks, no faces: $n_0 = 3$, $n_1 = 3$, $n_2 = 0$, with
$\dd_2 = 0$ and incidence matrix
\[ \dd_1 = \begin{pmatrix} 1 & 0 & 1 \\ 1 & 1 & 0 \\ 0 & 1 & 1 \end{pmatrix}
\quad \text{over } \FF. \]
\end{definition}

\begin{proposition}[triangle code parameters]
The triangle code is a $[[3,1,3]]$ code: $n = 3$, $k = 1$, $d = 3$.
\end{proposition}
\begin{proof}[Proof sketch]
The fundamental loop $v = (1,1,1)$ satisfies $\dd_1 v = 0$ (each vertex meets two
edges, $1+1=0$), so $v \in Z$; and $v \ne 0 = B$, so $v \notin B$ and $k \ge 1$ by
Theorem~\ref{thm:info}. The matrix has rank $2$, so by Theorem~\ref{thm:dim},
$k = 3 - 2 - 0 = 1$. For distance, $d \le |v| = 3$ by
Proposition~\ref{prop:ub}; every nonzero cycle lies in the $1$-dimensional kernel
$\langle(1,1,1)\rangle$ of weight $3$, and $d \ge 1$ by
Proposition~\ref{prop:pos}, so $d = 3$.
\end{proof}

\section{Algorithms}
\textbf{A (parameters).} From $\dd_1, \dd_2$ with $\dd_1\dd_2 = 0$, row-reduce to
get $r_1 = \rank\dd_1$, $r_2 = \rank\dd_2$, return $(n, k = n - r_1 - r_2)$; cost
$O(n^3)$. \textbf{B (homology basis).} Compute bases of $\ker\dd_1$ and $\im\dd_2$;
extend the boundary basis to a cycle basis; extra vectors are logical operators;
cost $O(n^3)$. \textbf{C (distance).} Enumerate the $2^k$ nontrivial cosets, keep
the minimum Hamming weight; exponential in general, exact for verification.

\section{Future directions}

\begin{conjecture}[homological packing bound]
For every CSS code arising from a $2$-complex embeddable in a closed surface,
$k \cdot d^2 \le c \cdot n$ for an absolute constant $c$, with equality approached
by regular toric layouts: a short cycle in one direction forces a short dual cut,
so rate and distance trade off quadratically.
\end{conjecture}

\begin{conjecture}[genus is the sole obstruction to rate]
Two closed orientable surfaces give CSS codes of equal logical dimension iff they
have equal genus; $k = \dim H_1$ is a homotopy invariant, blind to the
tessellation, which controls only $n$ and $d$.
\end{conjecture}

\begin{conjecture}[hyperbolic surfaces beat Euclidean ones]
Codes from negatively curved (genus $\ge 2$) tessellations achieve constant rate
$k/n$ bounded away from zero while retaining distance $\sim \log n$, beating flat
toric codes. Hyperbolic area grows with boundary length, so a fixed fraction of
cells can be handles without shrinking the systole as fast.
\end{conjecture}

\begin{conjecture}[color codes as quotient complexes]
Every color code on a $3$-valent, $3$-colorable $2$-complex is equivalent to a
surface code on an explicit branched double cover, with matching distance: folding
the colors realises the colored complex as an ordinary chain complex whose systole
is preserved by the cover.
\end{conjecture}

\section{Conclusion}
The three CSS parameters are three classical invariants of a cellular space: $n$
is the number of $1$-cells, $k = \dim H_1$ the first Betti number, and $d$ the
systole. The Dimension Theorem, the Information Criterion, the Genus Theorem with
its Euler-characteristic corollary, and the systolic theory of distance give a
self-contained algebraic-topological foundation for topological quantum error
correction, illustrated on the $[[3,1,3]]$ triangle code.

\end{document}

