function CODE_PARAMETERS(d1, d2, n):
    r1 <- RANK_F2(d1)          # Gaussian elimination over F2
    r2 <- RANK_F2(d2)
    k  <- n - r1 - r2          # CSS Dimension Theorem
    return (n, k)

function RANK_F2(M):
    piv <- 0; rank <- 0
    for each column c:
        find row r >= piv with M[r][c] = 1
        if none: continue
        swap rows piv and r
        for every other row s with M[s][c] = 1:
            M[s] <- M[s] XOR M[piv]
        piv <- piv + 1; rank <- rank + 1
    return rank

