function HOMOLOGY_REPS(d1, d2, n, n2):
    B <- { d2 * x : x in F2^{n2} }   # boundaries
    seen <- copy(B)
    reps <- []
    for v in F2^n:
        if d1 * v = 0 and v not in seen:
            append v to reps
            for b in B: add (v XOR b) to seen
    return reps

function SYSTOLE(d1, d2, n, n2):
    B <- { d2 * x : x in F2^{n2} }
    best <- infinity
    for v in F2^n:
        if d1 * v = 0 and v not in B:
            best <- min(best, weight(v))
    return best

